INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Facility 47', 'After waking up alone in an icy cell, you find that you''ve been left with only a letter and a bottle of pills. To find out how you got here, you''ll have to escape and begin a journey through an isolated research facility in the freezing depths of the Antarctic. Solve puzzles as you go and unlock new locations around the Facility. As you explore, you can search for clues that will help you piece together the mysterious history of Facility 47 and how exactly you came to be there!' FROM games WHERE igdb_id = 90790 ON CONFLICT (game_id, language_code) DO NOTHING;
