INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caretaker Sacrifice', 'Narrated by David Hewlett of Stargate, Caretaker Sacrifice is an epic sci-fi 6DOF adventure puzzle shooter game set in the far future. At the end of time, delve into the twisting innards of this hostile alien machine, through peril and adventure, to puzzle out and solve the ultimate mystery of what happened to the universe. Fulfill your final mission. In every sense, it’s a cerebral descent.' FROM games WHERE igdb_id = 18353 ON CONFLICT (game_id, language_code) DO NOTHING;
