INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghostbusters Arcade', 'Ghostbusters Arcade is a video redemption game developed by the arcade masters at Play Mechanix for ICE. Players confront ghosts on two levels which are based on events from the first two Ghostbuster films. They then have to stop the Stay Puft Marshmellow man for the chance at a big ticket bonus!' FROM games WHERE igdb_id = 221057 ON CONFLICT (game_id, language_code) DO NOTHING;
