INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Known Unknowns', 'Nadia Nazari has a lot of unknowns to contend with in her Grade 12 year. Like how can she run an entire school newspaper with only one employee? Why has her estranged ex best friend suddenly come back into her life? How is her long-term boyfriend going to react when he finds out she''s bisexual? And oh yeah — WHAT''S UP WITH ALL THE FREAKY GHOST RACCOONS HAUNTING HER HIGH SCHOOL??' FROM games WHERE igdb_id = 139309 ON CONFLICT (game_id, language_code) DO NOTHING;
