INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arkham Nightmares', 'Arkham Nightmares is an adventure game with rogue-like elements. You play Prof. Liebwerk the head physician of the Lovecraftian Arkham Sanatorium. Your task is to complete your journal with all the stories from the crazy inmates. But before they will tell you anything you have to win their trust.' FROM games WHERE igdb_id = 31700 ON CONFLICT (game_id, language_code) DO NOTHING;
