INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Theatrhythm Final Fantasy: All-Star Carnival', 'Theatrhythm Final Fantasy All-Star Carnival is an arcade rhythm video game and the successor to the Theatrhythm series of rhythm games that were originally released on the Nintendo 3DS. The game features revamped arcade controls, improved graphics, cooperative play, and songs and characters that were not featured in previous versions. As with many modern arcade games, All-Star Carnival is network-enabled and is continuously being updated with new content.' FROM games WHERE igdb_id = 57793 ON CONFLICT (game_id, language_code) DO NOTHING;
