INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'XorceD - Sashiro''s Laedrum', 'Play as Sashiro Kobata, a World-Peacemaker (WPM) officer with an incredible dual-wielding pistol skill, in an undercover mission! His WPM-group has found out information about a terrorist group. The information: A highschool student is supposed to be the leader of that terrorist group! In order to maintain world-peace and to stop the terrorist group, Sashiro has to identify the leader by transferring to the school as a student. Will he be able to find out the truth?' FROM games WHERE igdb_id = 33432 ON CONFLICT (game_id, language_code) DO NOTHING;
