INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stranger-of-sword-city-limited-edition', 42681, '2016-05-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9h5b.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stranger of Sword City: Limited Edition', 'From the dungeon crawling geniuses behind Demon Gaze, this new title takes a decidedly more Western approach to the traditional dungeon crawler and infuses the game with dark fantasy themes, new gameplay elements, and the ability to compete with fellow players through a leaderboard system. At its core it''s a game about death and fighting against vanishing forever. You will discover new meaning in the choices you make to survive against all odds. You will define yourself by the lives of those you leave behind, by the people you align yourself with, and the experiences you have on each new venture into the dark labyrinths that threaten to trap you. Your flight crashes after passing through a mysterious portal. As the sole survivor, you awaken to an unfamiliar land lit by stars you''ve never seen. This land is Escario, the city of swords. Quickly marked as the Chosen One, the Stranger of Sword City, you must defend this place, and choose your allegiances carefully as you scour the land for a way home.' FROM games WHERE igdb_id = 42681 ON CONFLICT (game_id, language_code) DO NOTHING;
