INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Duel Monsters Saikyo Card Battle', 'Yu-Gi-Oh! Duel Monsters Saikyo Card Battle is a digital-only card battle game for the Nintendo 3DS. Players take the role of a novice duelist who enters the Legend Challenge tournament, hosted by KaibaCorp, with the goal of challenging the Duel King. The game serves as an introduction to dueling, following Speed Duel rules for all duels, further simplified by not using a Side Deck and not including Ritual Monster Cards, Ritual Spell Cards, Quick-Play Spell Cards, Field Spell Cards, Continuous Trap Cards and Counter Trap Cards.' FROM games WHERE igdb_id = 58652 ON CONFLICT (game_id, language_code) DO NOTHING;
