INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('once-in-yaissor', 30577, '2016-11-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co53yw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1t2e.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Once in Yaissor', 'Лето, 2020 год, Яиссор. Большая часть людей стали ютуберами, стримерами и прочим скамом, почти никто не хочет быть работящим быдлом. Своего мнения никто не имеет. Все возомнили себя нигилистами, атеистами, читающими интеллектуалами и прочей элитой. Но жизнь быдла не изменилась, ведь все люди, что гонят на это быдло им же и является. Поэтому Яиссор больше не Европа-Азия, теперь она Атеисто-Быдло. Во главе Атеисто находятся сами люди, а точнее те, кто занимается интернет деятельностью. Во главе Быдло стоит Нитуп и именно эта часть страны снабжает Россию всем необходимым производством, ведь в Атеисто живут люди, которые считают, что работа для отсталых в развитии людей.' FROM games WHERE igdb_id = 30577 ON CONFLICT (game_id, language_code) DO NOTHING;
