INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi mix: Spacy mix ver.', 'Tamagotchi m!x is a color-screened Tamagotchi released exclusively in Japan on July 16, 2016. It introduces the m!x feature which allows the user to create Tamagotchis that are a mix of their parent''s features. The Spacy mix version features exclusive access to Spacy Land and its characters.' FROM games WHERE igdb_id = 230031 ON CONFLICT (game_id, language_code) DO NOTHING;
