INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('evolution', 34674, '2016-06-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa21c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tmkafm58phldn846bnrs.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evolution', 'Evolution is a real time simulation of the evolutionary process. Creatures have DNA that defines their structure, traits, how they see the world around them, and how they react to it. Each creature is unique, most die quickly, some die a little slower, and others survive (some just like rocks, they usually die too). It is the survivors that reproduce and mutate, just a little, but enough to adapt to their environment. Early creatures are pretty basic but they have the capacity for some pretty elaborate behaviors and, to be honest, I am not sure how interesting this could get.' FROM games WHERE igdb_id = 34674 ON CONFLICT (game_id, language_code) DO NOTHING;
