INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Ga-Olé', 'Pokémon Ga-Olé is an arcade game developed by Takara Tomy A.R.T.S. and Marvelous, which also developed the Pokémon Battrio and Pokémon Tretta arcade games. Pokémon Ga-Olé was officially announced on April 13, 2016 at the Takara Tomy A.R.T.S. 2016 Summer Business Meeting in Tokyo by Takara Tomy A.R.T.S. president & CEO Hiroyuki Usami and Marvelous vice chairman Shuichi Kyoda. It was launched nationwide in Japan on July 7, 2016. The machines were later launched in Taiwan in Traditional Chinese beginning on December 5, 2020, Mainland China in Simplified Chinese beginning on December 12, 2020, South Korea in Korean beginning on August 2, 2021, Hong Kong in English beginning on October 13, 2021, Singapore in English beginning on November 17, 2021, and Malaysia in English beginning on January 27, 2022.' FROM games WHERE igdb_id = 131487 ON CONFLICT (game_id, language_code) DO NOTHING;
