INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fated Souls 2', 'A brave warrior named Galahar goes back to his hometown after 10 years of searching for his kidnapped daughter, who disappeared during raid at their village. Soon after arriving home at Solside Village, he is selected by the Mershiak Church to become a Swordmaster. While at first he thinks this would divert him from his primary objective, finding his daughter, he discovers that both paths are strangely connected.' FROM games WHERE igdb_id = 31407 ON CONFLICT (game_id, language_code) DO NOTHING;
