INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tinker Island', 'In this game you find yourself being cast away on a tropical island. Become the leader of survivors in this lost paradise. Take them on an adventure of a lifetime - build a base, explore mysteries or forage treasures. Learn the art of crafting, foraging and exploring but keep in mind, there is never an idle moment in the everyday lives of the survivors.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 134148 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
