INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Vikings: Ragnarök Edition', 'In a desperate move, Odin has reanimated Gunborg, Seagurd, Hedgy and Caw-Kaa, four of the most terrifying Viking zombies who have ever lived. This putrid team will embark on a mission in the most epic of worlds. Not only to recover the magical eye, but also to honor its roots. ZOMBIE VIKINGS: RAGNAROK includes: 2 extra characters, 5 combat arenas and a digital art book.' FROM games WHERE igdb_id = 166962 ON CONFLICT (game_id, language_code) DO NOTHING;
