INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bridge to Nowhere', 'Are you looking for a brief, immersive, and exciting experience to demo VR to first-time users? What about a quick way to get your heart pumping? Then Bridge to Nowhere is the game for you. Step onto a squeaky bridge 80 feet in the air as high winds surround you. Do you have what it takes to jump off?' FROM games WHERE igdb_id = 30989 ON CONFLICT (game_id, language_code) DO NOTHING;
