INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sudden Attack 2', 'The game featured much of the same modes and play styles from the original game with added customization for characters and a newer game engine which allowed for more updated graphics. Launched in July 2016, Sudden Attack 2 was shut down 23 days later due to an end of contract with the game developer. Plans for a Japanese launch of the game were never realized due to the abrupt shutdown of its servers.' FROM games WHERE igdb_id = 317135 ON CONFLICT (game_id, language_code) DO NOTHING;
