INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Depression Presented Ludically in the Style of a Videogame', 'Depression Presented Ludically in the Style of a Videogame isn''t a hopeful game, but there''s something positive to be found in it: if the cognitive distortions that depression brings with it can be so effectively portrayed in such a tiny game, then clearly none of us are alone in those thoughts.' FROM games WHERE igdb_id = 342905 ON CONFLICT (game_id, language_code) DO NOTHING;
