INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ThrounnelVR', 'ThrounnelVR is a tetris-like puzzler with a first-person view. The goal of ThrounnelVR is to fit the shape of blocks into a distant hole. You control the movement of the blocks by your HMD, and the rotation by game controller or keyboard. The speed of the blocks increases and the shape becomes move complex, so you have to be quick as the game goes on.' FROM games WHERE igdb_id = 31877 ON CONFLICT (game_id, language_code) DO NOTHING;
