INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('playthings-vr-music-vacation', 32881, '2016-08-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xpa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7vk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Playthings: VR Music Vacation', 'Playthings: VR Music Vacation is a virtual reality music playground for the HTC Vive. Set on a tropical island where you hit bouncy, musical food with drumsticks, Playthings is sure to delight whether or not you’re a musician or a gamer. You don''t need lessons to play gummy bears, and music masters will be making sweet symphonies in no time at all. Teleport around a hypercolor fantasy landscape with psychedelic portals, unlock kitchen tools that can rearrange the world around you, and climb the summit of a two story barbeque grill. Lose your body to a rhythm game full of flying hot dogs and hamburger drums, featuring original music by future-funk idols George & Jonathan. If Lisa Frank, George Foreman and Michael Jackson made a video game, the result would be Playthings.' FROM games WHERE igdb_id = 32881 ON CONFLICT (game_id, language_code) DO NOTHING;
