INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlefield 1: Standard Collector''s Edition', 'Welcome to the Battlefield 1 Collector''s Edition. This is your chance to own a piece of Battlefield history. Enhance your setup with the 14” statue, which any true fan will be proud to own. Go behind the scenes to discover more about the game''s creation through the concept art playing cards, uncover exclusive DLC content with the messenger pigeon tube and join the fight wearing your very own Battlefield patch. Heck, you can even start recruiting allies with the cloth poster.' FROM games WHERE igdb_id = 112637 ON CONFLICT (game_id, language_code) DO NOTHING;
