INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hearts-of-iron-iv-hero-edition', 47308, '2016-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/yivnq2o72yxaionxtx1m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6dzd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hearts of Iron IV: Hero Edition', 'You are now in command of World War II! Your ability to lead your nation is your supreme weapon, the strategy game Hearts of Iron IV lets you take command of any nation in World War II; the most engaging conflict in world history. From the heart of the battlefield to the command centre, you will guide your nation to glory and wage war, negotiate or invade. You hold the power to tip the very balance of WWII. It is time to show your ability as the greatest military leader in the world. Will you relive or change history? Will you change the fate of the world? Death or Dishonour DLC: Death or Dishonour is a new Country Pack for Hearts of Iron IV, and expands upon players'' ability to experience history''s greatest conflict from any point of view. This new pack focuses on the countries caught between the Soviet Union and Nazi Germany during World War II - faced with the tough choices of starting a conflict with a global superpower, or compromising their ideals to strike a deal for their own survival. Together for Victory DLC: New national focus trees and events for Canada, Australia, New Zealand, The Raj (India) and South Africa. Alternate historical path for each of the Dominions, with options to stay loyal to Great Britain, or forge a new, more independent destiny.' FROM games WHERE igdb_id = 47308 ON CONFLICT (game_id, language_code) DO NOTHING;
