INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('king-lucas', 26371, '2016-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1zud.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc02.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King Lucas', 'After an affair King Lucas had with the Witch of Sausan, the Queen left him and remarried in an adjacent kingdom, and now his daughters are the only ones left at his side. Due to his love for them, each and every time they get lost in the castle, he moves heaven and earth to get them back and he only resorts to the most intrepid knights in order to find them. Will you be one of those knights? 
