INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('popgoes-arcade', 140319, '2016-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co66jb.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Popgoes Arcade', 'In Popgoes Arcade, you play as a child. You’re not going to be killed by a mysterious man, you’re not going to be stuffed into a suit or given a mask to wear in purgatory. No. Today, you’re just going to play a damn game on a top-of-the-line Popgoes Pizzeria arcade machine. You’re going to play Weasel World. Your favourite. But Weasel World feels… strange today. It plays the same, it looks the same, it... smells the same... But there’s just something wrong about it. And with your little hand at the joystick, you WILL find out what that something is. Until your parents come to pick you up, of course.' FROM games WHERE igdb_id = 140319 ON CONFLICT (game_id, language_code) DO NOTHING;
