INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hagane Orchestra', '"Hagane Orchestra" is a tactical combat game where players command customized armored vehicles called "Hagane." Set in an unforgiving world, players use a real-time, touch-drawn tactical system to maneuver their Hagane and engage in strategic battles. Players customize their vehicles using parts acquired through combat and gacha mechanics.' FROM games WHERE igdb_id = 393562 ON CONFLICT (game_id, language_code) DO NOTHING;
