INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Relativity', 'Relativity will turn your world upside down. Curved surfaces and stairs allow you to walk from the floor, up the walls and across ceilings, shifting gravity and giving you a whole new perspective! Landscape platforms can be moved and rotated using buttons and wheels to transform the landscape and form bridges. If that isn''t challenge enough, there are dragons, jumping crabs, killer robots, laser beams and devious puzzles to contend with.' FROM games WHERE igdb_id = 31637 ON CONFLICT (game_id, language_code) DO NOTHING;
