INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Highway to the Moon', 'Highway to the Moon is a fast-paced scrolling arcade shooter where you take control of Jacob Helaway, stunt man and thrill-seeker extraordinaire, as he makes his way to the Moon in pursuit of the interstellar criminal known only as the Moon Man. You’ll have your work cut out for you though, because between the Unger Max Gang, Air Traffic Control, Alien Affairs, and Leadersquad, it looks like everyone wants a piece of the Moon Man.' FROM games WHERE igdb_id = 32890 ON CONFLICT (game_id, language_code) DO NOTHING;
