INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('thrift-store-story', 106920, '2016-09-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7cwm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sce025.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thrift Store Story', 'Become the manager of a pre-loved goods store (yup, that''s just a fancy name for second-hand!) and turn it into a prospering business! There are many towns for you to operate in, each with a unique customer base and different products for you to discover. You can guess what you''ll find in Trendy Town or Totaltoys District, for example! The product line-up at your store is up to you, of course. Will you be selling model toys, video games, classy suits, cars, plasma TVs, or diamonds? That''s the fun in the second-hand retail industry - you sell all sorts of goods, cherry-picked from a variety of available pre-owned products. Your store also offers a gift-wrapping service which does wonders for boosting customer satisfaction. Besides store shelves, you can also have stalls selling donuts or ice-cream, a gaming corner or toy vending machine. They''ll draw in more customers, and once your store becomes really popular, even whole groups of kids or curious tourists. Your field staff are in charge of collecting goods for sale. They''ll sometimes come across what looks like real treasure, but you''ll have to appraise it first to see what it''s actually worth. You may discover some amazing items this way, which will bring fame to your store! Fully exploring every town and finding all available products is a real challenge... Are you up for it?' FROM games WHERE igdb_id = 106920 ON CONFLICT (game_id, language_code) DO NOTHING;
