INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA 2KVR Experience', 'In the NBA 2KVR Experience, players will join NBA 2K17 cover athlete and All-Star Paul George, as they step onto the court at the Indiana Pacers’ stadium, Bankers Life Fieldhouse. Paul George will also provide commentary and guide the player by offering tips to help improve their skills in mini-games and features including three-point shootout, a speed and accuracy skills challenge, the buzzer beater countdown. Players who can earn a variety of Gatorade boosts that will aide their shooting acumen, speed, recovery and more to help reach the top of the leaderboards.' FROM games WHERE igdb_id = 25907 ON CONFLICT (game_id, language_code) DO NOTHING;
