INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sea Hero Quest', 'Sea Hero Quest is a mobile game which contributes to research on dementia. It was designed by British game company Glitchers in 2016 in association with Alzheimer''s Research UK, University College London and the University of East Anglia and with funding from Deutsche Telekom. The idea for the game came from neuroscientist Michael Hornberger of the University of East Anglia who collaborated with Hugo Spiers of University College London and a group of six other neuroscientist.
