INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magdalena', 'The mind dissolves in the surrounding darkness like pain dissolves in wine. Remains of memories crumble and rapidly leak like sand through fingers. And only one name stuck in the throat filled with fear. Magdalena... Minutes feel like days while waiting for something to happen.' FROM games WHERE igdb_id = 33779 ON CONFLICT (game_id, language_code) DO NOTHING;
