INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warshift', 'WARSHIFT is a unique mix of Action, Strategy, Role-playing gameplay elements that forms an innovative game genre. You can collect resources, build bases, manage armies, and then come down to keep the enemies at gunpoint, gain experience in dynamic battles and customize your main characters or vehicles. It requires a complete change of your play style.' FROM games WHERE igdb_id = 14075 ON CONFLICT (game_id, language_code) DO NOTHING;
