INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Puzzle', 'Far away, lost in another dimension, there‘s a world where human dreams come to life. A land built upon sweet dreams where Trekkie and her friends live, safe from the bitter monsters inhabiting the dark world of nightmares. But even all the fear and anguish in the land of the human aren''t enough for the nightmare monsters, who are stealing the dreams of Trekkie‘s world, keeping them hidden while dreams are corrupted and transformed into nightmares. Help Trekkie ﬁnd their dreams before it‘s too late!' FROM games WHERE igdb_id = 32304 ON CONFLICT (game_id, language_code) DO NOTHING;
