INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-magical-high-school-girl', 30533, '2016-11-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7lhn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar994.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Magical High School Girl', 'A Magical High School Girl is an isometric grid-based turn-based roguelike RPG. However, unlike normal roguelikes, the HP system, experience system, levels, UI, and almost everything else has been reimagined to fit the theme of the game. And most of all this is the first roguelike to offer an enjoyable experience for even casual players. But this game has many layers, and even roguelike veterans will have something to look forward to in the diverse systems this game has to offer. The same combination of words will always create the same spell, so tell your friends about the spells you discover and use the knowledge you''ve hoarded to beat others in time attack mode. There''s all sorts of ways to play!' FROM games WHERE igdb_id = 30533 ON CONFLICT (game_id, language_code) DO NOTHING;
