INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fortify', 'Fortify is a real-time strategy game with a tower defense twist. Defend your castle from attacking monsters and siege weapons by using ranged and melee defenders, catapults, cannons, oil fields and more. You start at the iron age, advancing to the medieval age,  and later, the imperial age. Each new age enables important upgrades and allows for new techniques to defend your castle.' FROM games WHERE igdb_id = 35030 ON CONFLICT (game_id, language_code) DO NOTHING;
