INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Quiz', 'Come and test your trivia skills with the latest addictive QUIZ game - Donkey Quiz by Octro. Take the ride of knowledge on Donkey Quiz Game with fun and interesting trivia questions. Exercise your mind with educational multiplayer brain game. Challenge your friends to achieve the highest score in the trivia fun quiz.' FROM games WHERE igdb_id = 263406 ON CONFLICT (game_id, language_code) DO NOTHING;
