INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Machine Learning: Episode I', 'Machine Learning: Episode I is a first person arcade puzzle game built for HTC Vive. You play as an A.I. robot created in DARPA laboratory in the near future. One of the scientists is here to test your physical, perception and cognitive skills. By using the power of room-scale VR and Vive controllers, you will be solving a variety of unique puzzles.' FROM games WHERE igdb_id = 90571 ON CONFLICT (game_id, language_code) DO NOTHING;
