INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moana: Rhythm Run', 'Find your rhythm… chase your destiny. Tap your way through this rhythmic, action-adventure game featuring music from the new Disney film, Moana! Play as both Moana and Maui as you journey to restore the Heart of Te Fiti. Voyage to distant islands, take on Kakamora pirate ships, and battle in the Realm of Monsters. Experience the unforgettable music directly from the Moana film as you sail, jump, run, and fight your way to save the day and discover your destiny.' FROM games WHERE igdb_id = 97981 ON CONFLICT (game_id, language_code) DO NOTHING;
