INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Holodaze', 'Fight your way through wave after wave of deadly robot drones by throwing your trusty powerball in their faces. Be sure to get out of the way of their shots back though by dodging or teleporting to another cube. Beware though, the face of the cube you point at is where you''ll end up, so you could end up being upside down with gravity working against your throw.' FROM games WHERE igdb_id = 32566 ON CONFLICT (game_id, language_code) DO NOTHING;
