INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kiya', 'Kiya is a five minute virtual reality piece telling the story of two sisters valiant but unsuccessful efforts to try to rescue their third sister, Kiya, from a deadly attack by her ex-boyfriend. Using two separate recorded calls to emergency workers, the experience puts the viewer on scene as the tragic events unfold. With three women killed every day by their intimate partners in the United States, Kiya is ultimately a call to action: this should never happen to anyone’s sister again.' FROM games WHERE igdb_id = 33670 ON CONFLICT (game_id, language_code) DO NOTHING;
