INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zenza', 'Zenza is a calming yet strategic puzzle game based off of Kigo Haiku, a form of Japanese poems thematically relating to the seasons. Put colors or shapes together to achieve balance. Progress through increasingly challenging levels to perfect your zen. Leaves, blossoms or snow may fall, slices and wind by cut your mistakes, there''s always a chance to start anew.' FROM games WHERE igdb_id = 25949 ON CONFLICT (game_id, language_code) DO NOTHING;
