INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pretty Please', 'Make me pretty please. A short game about a lady who goes into a beauty clinic to "fix a few things". Features several endings and beautiful artwork, made in 3 days for a game jam. The game contains 497 dialogue blocks, containing 3,644 words and 19,587 characters, for an average of 7.3 words and 39 characters per block. The game contains 11 menus, 15 images, 14 screens, and a total of 3 possible endings.' FROM games WHERE igdb_id = 177384 ON CONFLICT (game_id, language_code) DO NOTHING;
