INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fidchell', 'Fidchell, which is also called Faery Chess or Celtic Chess, is an ancient celtic game which was mentioned in multiple Irish epics and chronicles. Under the name of Gwyddbwyll it also appears in the Welsh Mabinogion and seems to have been held in peculiar reverence throughout the British Isles. Faery Chess is what emerged from Nigel Suckling''s investigations and speculations about the lost game.' FROM games WHERE igdb_id = 139338 ON CONFLICT (game_id, language_code) DO NOTHING;
