INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'KanColle Kai', 'KanColle Kai is the Playstation Vita version of the popular Japanese online browser game Kantai Collection, where the player is put in charge of a navy consisting of moe anthropomorphisms of World War 2 warships known as "fleet girls". It introduces various strategy elements such as hexagonal maps, in addition to a new resource transfer and escort system. Some maps within the game will allow two separate fleets to operate simultaneously, and the player is able to change the tempo of the game. Existing functions from the original web browser game will also be present, with major user interface changes.' FROM games WHERE igdb_id = 11461 ON CONFLICT (game_id, language_code) DO NOTHING;
