INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Shell', 'You''re commanding a die-hard assault squad. Destination: Plutonia, a settlement on a Doom-4 class planet. Shuttle cargo: a range of lethal weapons, from axes and chainsaws to blasters and BFGs. Anything might come in handy in Plutonia, the Federation''s most remote colony.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 193943 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
