INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Island 359', 'Island 359 is a Virtual Reality survival game for the HTC Vive and Oculus Rift+Touch. Players will use the guns, knives, upgrades, and other tools found on the island to survive for as long as they can against hordes of dinosaurs, as they explore the increasingly dangerous island. You''re a mercenary, and the money''s no good to you if you''re dead, so you''re going to need to get back to the chopper for an extraction if you want bragging rights and a big high score.' FROM games WHERE igdb_id = 32585 ON CONFLICT (game_id, language_code) DO NOTHING;
