INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Istrolid', 'In Istrolid you design your own unique spaceships from a large number of parts to fit your strategy and play style. With no set units or factions you are free to create a fleet where each ship has its own balanced strengths and weaknesses, from basic fighters and bombers to hulking battleships and speedy destroyers.' FROM games WHERE igdb_id = 33326 ON CONFLICT (game_id, language_code) DO NOTHING;
