INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Directionless', 'Directionless is an experimental Virtual Reality horror game. It tries out a variety of ways of using Virtual Reality to unnerve and disorient the player, with carefully crafted audio working with an interactive environment to pull you into a nightmarish world where you can''t trust anything.' FROM games WHERE igdb_id = 32502 ON CONFLICT (game_id, language_code) DO NOTHING;
