INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SCP: Unity', 'SCP: Unity is a game created by the development team Aerie Gaming Studios, headed by Zornor90. It is heavily inspired by the original SCP: Containment Breach. While the game was once a simple port and graphics upgrade, the project has since been expanded to encompass a wider array of content, including but not limited to graphical improvements, new SCPs, and a deeper story.' FROM games WHERE igdb_id = 130903 ON CONFLICT (game_id, language_code) DO NOTHING;
