INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('puzzle-scape', 46021, '2016-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1psy.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle Scape', 'Escape to block-busting puzzles and pulsating beats in this exciting new puzzle game for your PSP® system! Be entranced by brilliant, interactive evolutionary backgrounds from cells to dream-like landscapes in four unique themes over 40 levels. Level by addictive level, unlock fresh colors and luscious beats in either time and goal-oriented play or score-oriented play. Play solo or, in multiplayer mode, take on a single opponent or up to 8 other people, or team up and compete against another team.Send friends a demo of the game via the PSP® system’s wireless functionality.' FROM games WHERE igdb_id = 46021 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 46021 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
