INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abrix the robot', 'Abrix the robot is an addictive puzzle game for everyone. The game provides over 40 hours of intellectual entertainment ranging from fairly simple puzzles, to the extremely difficult, forcing the player to maximum effort. You can also create your own rooms with the editor, make them available in the Steam workshop and invite your friends to play. Challenge them and see if they solve the puzzles designed by you!' FROM games WHERE igdb_id = 33018 ON CONFLICT (game_id, language_code) DO NOTHING;
