INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taxi', 'A sliding Tile puzzle game with 29 levels ranging from easy to skull cracking. A killer soundtrack and great visuals make this a must play game! Try to get the taxi from start to the airport on each level. Bonuses are given based on how fast you solve the puzzle, how far the taxi travels, and if you go through an intersection tile both ways.' FROM games WHERE igdb_id = 36490 ON CONFLICT (game_id, language_code) DO NOTHING;
