INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kira-kira Star Night DX', 'Kira Kira Star Night DX follows Fami-chan. She’s a young woman jumping around environments, attempting to catch stars while chiptunes play in the background. The goal is to get a certain number of stars before time runs out. There are nine stages total, and the game features music from Takeaki Kunimoto, Yuriko Keino, Yuzo Koshiro, Nobuyuki Koshiro, Tappy, Manami Matsumae, Hally, Bun, Robokabuto, Yasuhisa Watanabe, and Takeshi Yokemura.' FROM games WHERE igdb_id = 48932 ON CONFLICT (game_id, language_code) DO NOTHING;
