INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let Hawaii Happen VR', 'Visiting Hawaii as a tourist is amazing. But when you get to “Let Hawaii Happen” with a local as your guide, it’s a totally different experience. Start by paragliding into an island of your choice. Then, upon landing, a local will give you the most personal tour of their island — virtually-speaking.' FROM games WHERE igdb_id = 31151 ON CONFLICT (game_id, language_code) DO NOTHING;
