INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phoenix Wright: Ace Attorney - The Jakkid Series', 'Set in an alternate universe, Phoenix Wright must defend... anyone who needs it. Whether they live in his world or not. This game features ten extremely high-quality fanfictions made by the author Jakkid166. The game is mostly faithful to the source, including the author''s writing style and language, though there are a few changes made for gameplay purposes. No censorship -- Phoenix Wright can and will say fuck!' FROM games WHERE igdb_id = 302601 ON CONFLICT (game_id, language_code) DO NOTHING;
