INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rayne the Rogue', 'As a child Rayne watched the rich from the streets of the village and burned with jealousy. After years and years of poverty an idea formed. Rayne has decided to sneak into the lairs of dragons and steel their treasures. Rayne need your help to navigate the dangerous caves and avoid the dragon’s breath to become the wealthiest person in the village, but take heed, the further Rayne gets the more treacherous it will be.' FROM games WHERE igdb_id = 256768 ON CONFLICT (game_id, language_code) DO NOTHING;
