INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Observatory: A VR Variety Pack', 'Observatory is a variety pack for VR headsets. It includes three games and a music video: Procedural downhill racing, spacejet-horror with microscopic submarines, island-puzzling with physics-based creatures, and a trippy official music video for a song by Icky Blossoms.' FROM games WHERE igdb_id = 19062 ON CONFLICT (game_id, language_code) DO NOTHING;
