INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Trader 2018', 'Travel the galaxy, become an expert trader, fight pirates, and run from the police in Space Trader! A much-anticipated remake of the hugely popular, timeless strategy game from the 1980s, Space Trader is a historically accurate port of the original Palm Pilot game by Pieter Spronck. It features the original ten commodities and more than 100 original planets, each with unique tech levels, governments, resources, and other characteristics.' FROM games WHERE igdb_id = 197805 ON CONFLICT (game_id, language_code) DO NOTHING;
