INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Even in Arcadia, There I Am', '"Even in Arcadia, There I Am" is a short, experimental game about memory, escape, and whatever else you happen to think it''s about. Maybe death? That would be deep, right? There is no win state, and there are no puzzles, but there is one "link" to another world (this was submitted to Mystjam, after all). It shouldn''t be too difficult to find.' FROM games WHERE igdb_id = 136421 ON CONFLICT (game_id, language_code) DO NOTHING;
