INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Badminton VR', 'Space Badminton is the worlds first VR Badminton simulation. It will test your true badminton skills against a sophisticated and skilled artificially intelligent space robot. You will fight against the AI robot to become the badminton champion. Space Badminton takes place in the deep space, where you are given the power to defy GRAVITY by the power of jet boosters. Use this to your advantage in defeating the AI robot. Good Luck !!!' FROM games WHERE igdb_id = 29853 ON CONFLICT (game_id, language_code) DO NOTHING;
