INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Break Through: Artificial Maze', 'This is a 3D maze adventure puzzle game with a unique story and gameplay elements. Players can choose to control the protagonist by switching the soul freely between three unique characters - human, dog, or Eagle. The human is the basic character, and has a gun he can use to take out enemies. Dog''s special skill is its perspective can be used to discover hidden enemies and items. Eagle''s special skill is that it can fly a short distance to view the terrain routes.' FROM games WHERE igdb_id = 33204 ON CONFLICT (game_id, language_code) DO NOTHING;
