INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('corpse-party-back-to-school-edition', 47669, '2016-11-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4or2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgpqe.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corpse Party: Back to School Edition', 'Kisaragi Academy student Mayu Suzumoto is transferring to a new high school, leaving behind a sizable group of friends and countless lovely memories. To help her cope with this move, her friend Ayumi has devised a seemingly innocent plan: the whole group will come together to perform a charm she found on the internet called “Sachiko Ever After,” which is supposed to bind all of its participants together as friends to the end. This does not go as expected. Following an intense earthquake, the group awakens to find themselves separated and trapped in an alternate reality version of Heavenly Host Elementary School, a tragedy-stricken institution that once stood on the site of their own school but was torn down long ago. Here, the vengeful spirits of elementary-aged children threaten their lives and their sanity, and the only hope of survival - much less escape - is to uncover the chilling details surrounding the murders of those trapped before them. Having previously gained a considerable fan base when released digitally on the PSP system, this reimagining on the Nintendo 3DS system represents the first time the original cult classic horror title that spawned a new indie sub-genre will see a physical release in North America. Exclusive new features include 3D art stills, Touch Screen menus, four additional Extra Chapters, expanded story scenes, an in-game character encyclopedia, redrawn character sprites, and newly arranged music tracks. This is the definitive version of the classic horror tale that spans over 50 years of tragedy, where player choices determine both how the story ends and who lives to see it through.' FROM games WHERE igdb_id = 47669 ON CONFLICT (game_id, language_code) DO NOTHING;
