INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eatvolve', 'Eatvolve is an evolutionary eat-em-up, elevating a lowly worm to the ultimate hybrid organism by gobbling up other critters - and stealing their unique abilities! Freely explore a colourful world of adorable, edible animals and combine their powers to find new ways to get around, powerful attacks, and more. Be careful, though: only one species can be the pinnacle of evolution, and competition is fierce!' FROM games WHERE igdb_id = 146481 ON CONFLICT (game_id, language_code) DO NOTHING;
