INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GooCubelets: The Algoorithm', 'Billions of year ago in a faraway goolaxy living organisms were combined with the goo nebula formulae. And the Algoorithm was created. Time has passed, and the Algoorithm remained incomplete... You are given a chance to solve the last 50 equations! But be careful, even a small mistake could end everything!' FROM games WHERE igdb_id = 33843 ON CONFLICT (game_id, language_code) DO NOTHING;
