INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-hand-of-panda', 85436, '2016-03-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ccu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9kgu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hand of Panda', 'The Hand of Panda is a fast action, memory and reflex game inspired by the bonus rounds commonly found in famous fighting games. Learn to focus your chi into a single strike by breaking orbs and channel your power to blow away a variey of challenging materials. Find ways to increase your score, to achieve legendary combos and to avoid distraction by your Master as you time your strike and finish off each item before the timer reaches zero. Journey with Panda, a unlikely character who is discovered by Master Koi, an old teacher who has ultimately mastery of "The Hand"; a legendary ability to break any item that crosses his path. With your teacher at your side, develop your smashing skills and climb the mystical pagodas that hold the worlds most difficult materials. Finish each tower to follow the story and ultimately discover a hidden truth.' FROM games WHERE igdb_id = 85436 ON CONFLICT (game_id, language_code) DO NOTHING;
