INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7Days!', 'Are you bored of the same old novels? Are you interested in interactive story games, visual novel, choice based storyline, and indie games, but you''re tired of the same old? Try our Adventure Game, a Mysterious Novel where choices do matter! We are offering our free interactive storytelling game named ‘7Days: Mystery Visual Novel, Adventure Game’. All our stories, mysterious novels are written by diligently selected authors.' FROM games WHERE igdb_id = 144716 ON CONFLICT (game_id, language_code) DO NOTHING;
