INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('psyche-soldier-vr', 30097, '2016-12-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobl4y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ujzk3aitfyey7azcbrgu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psyche Soldier VR', 'Psyche Soldier VR is a dynamic, duck-and-dodge shooting gallery game that takes place in the psychedelic realm of your own subconscious, tackling shadow creatures that embody Agency, Attachment, Fear, Procrastination, Shame, Stress, and Perfection. What sets this game apart from other games is its unique environment/setting, the action based power up that is both offensive and defensive, the strategic and athletic game play that arises from the variety of enemy abilities, the fluid energy system, and the engaging upgrade system. There''s also an infinite wave Endurance mode to see how deep into your subconscious you can go. And who knows, maybe you''ll learn something about your own shadow.' FROM games WHERE igdb_id = 30097 ON CONFLICT (game_id, language_code) DO NOTHING;
