INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bullet Life 2010', 'Bullet Life, originally released in 2010, was the very first video game ever designed as a full on 3D Bullet Hell Shooter. Fly through the skies as and blast your way through enemies with a more stratify based shooting system! Use guns, rockets, hover canons, and more and weave through hundreds of bullets!' FROM games WHERE igdb_id = 32641 ON CONFLICT (game_id, language_code) DO NOTHING;
