INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Tales: Her Own Eyes HD - A Hidden Object Mystery (Full)', 'Due to a successful new surgery, you’ve now been given back the gift of sight. The only problem is that you’re not only seeing the world around you, but you’re now seeing the dead as well. This new ability has taken you all the way to a town in Austria, where you must use your new vision to help the police solve a series of brutal crimes!' FROM games WHERE igdb_id = 90065 ON CONFLICT (game_id, language_code) DO NOTHING;
