INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hateful Dead', 'The Hateful Dead is a voxel style, wave-based, zombie FPS game. Run and gun with a Chainsaw in one hand and Minigun in the other as you stand alone against an army of the undead. Burn, cut, shoot and obliterate limbs from your undead enemies in an intense blood-splattered, shoot em up style. How long can you survive?' FROM games WHERE igdb_id = 31367 ON CONFLICT (game_id, language_code) DO NOTHING;
