INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO DC Super Heroes Chase', 'The LEGO DC Super Heroes Chase game is for the all the world’s greatest, secret 5-12-year-old Super Heroes and Super Villains. Players will enter a fun, action-packed story as one of their favorite DC Comics characters – and play as Superman, Batman, Wonder Woman, drive the coolest Super Hero vehicles to chase down Super Villains, and save the day! Or they can be a Super Villain like Bizarro, Killer Moth and Doomsday, and wreak havoc, and rule the world (or at least the city) as only an evil genius can!' FROM games WHERE igdb_id = 89137 ON CONFLICT (game_id, language_code) DO NOTHING;
