INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pythetron', 'Pythetron is a new evolution in the old school 2d shoot''em up (or shmup) genre built on a modern game engine utilizing advanced physics and 3d environments, with detailed models, animation, and sound. Pythetron takes a new direction in gameplay by allowing the game''s pacing to be controlled by the player and allowing the player to explore the galaxy in a non-linear manner by earning stars and unlocking new worlds.
