INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buried: An Interactive Story', 'Buried is a playable, interactive story told through stunning photos, a haunting soundscape, and gripping text. You play the role of  Roger Hastings, a logger working the forests with his crew. When he awakens to find his friends missing and no memory of what''s happened, he begins searching, uncovering something that should have stayed hidden...' FROM games WHERE igdb_id = 33689 ON CONFLICT (game_id, language_code) DO NOTHING;
