INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mafia III: Rivals', 'Begin your life of crime squaring off against rival gangs in battle RPG combat. Recruit and train 40 crime bosses from the Mafia III universe as they join your crew, and destroy any foes getting in the way. Outfit New Bordeaux''s newest hit squad with an assortment of deadly weaponry and other gear. Join up with friends and battle players worldwide to see who has the deadliest crew in New Bordeaux.' FROM games WHERE igdb_id = 78802 ON CONFLICT (game_id, language_code) DO NOTHING;
