INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dyadic', 'Two players steal an ancient and priceless relic, awakening an ominous presence deep beneath the earth, and sending them tumbling into long forgotten ruins. You both must work together to escape, yet you both want to be the one with the relic in the end. So, will you two be friends, or foes?' FROM games WHERE igdb_id = 33540 ON CONFLICT (game_id, language_code) DO NOTHING;
