INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Idol Death Game TV', 'Idol Death Game TV (Japanese: アイドルデスゲームTV Hepburn: Aidoru Desu Gēmu TV) is an action-adventure video game developed by Witchcraft and published by D3 Publisher for the PlayStation Vita with PlayStation TV support, released on October 20, 2016 in Japan. The game follows the starlets of the top idol group "Project 47" as they partake in an event titled "Dream of Dream" to become the central idol of the group. Those who fail in the competition are killed.' FROM games WHERE igdb_id = 79169 ON CONFLICT (game_id, language_code) DO NOTHING;
