INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Score a goal (Physical football)', 'It''s a physical game, whose main task is to score the ball into the goal. On your side and against you, only the laws of physics. All the controls in the game by using the computer mouse. Depending on the level will be various conditions of interaction of the player with the surrounding world. There are disappearing blocks, falling blocks, disappearing blocks, mines, ice, balls and so on.' FROM games WHERE igdb_id = 29951 ON CONFLICT (game_id, language_code) DO NOTHING;
