INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Days', 'The team that created White Night has gathered once again to offer you a hauntingly unique VR experience. Somewhere between Twin Peaks and The X-­Files, Dark Days is a new fantastic virtual reality adventure. You will have to discover what’s going on with an eerie desert motel and its surroundings by solving a number of puzzles. Immerse yourself in the rich environments you will come across, but be careful and smart! Something is roaming around you...' FROM games WHERE igdb_id = 170255 ON CONFLICT (game_id, language_code) DO NOTHING;
