INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turner', 'Turner is a 2D platformer puzzle game set in an insane asylum where you take the role of Turner, a man with a troubled past and an unstable state of mind. Complete over 500 levels by rotating the world around you. Solve a variety of puzzles, traverse through challenging levels, collect mysterious notes scattered throughout the asylum, and avoid dangerous obstacles, all while trying to solve the mystery of why you''re there.' FROM games WHERE igdb_id = 32375 ON CONFLICT (game_id, language_code) DO NOTHING;
