INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demon''s Sword', 'Demon''s Sword is a simple and completely unfair dungeon crawler in the vein of Telengard. Your goal is to collect a number of relics in order to defeat the demon Fulad-zereh, including the legendary Shamshir. You may cast spells or summon powerful demon lords for assistance, but at a dire cost to your Purity. Lose too much Purity and you shall join the damned wandering those accursed halls forever...' FROM games WHERE igdb_id = 127653 ON CONFLICT (game_id, language_code) DO NOTHING;
