INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Felt Tip Circus', 'Welcome to the smallest show on Earth! The lights are bright. The tension, real. The audience, demanding, even if they are made of wood. Now it’s your turn to compete in the greatest contest of skill ever to grace the miniature world of toys, trinkets and plain old junk! Throw knives; launch acrobats; walk tight-ropes; tame lions; hone your skills solo or compete with up to four friends in a race to win the crowd.' FROM games WHERE igdb_id = 33906 ON CONFLICT (game_id, language_code) DO NOTHING;
