INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('modern-zombie', 24943, '2016-10-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/palmoz6dw0r6camyhweb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fcggw5tbkudd6jdjpitq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Modern Zombie', 'The game is a horror-survival MMO, based on players enduring the hardships of a post-apocalyptic, zombie-infested world… By collaborating with other players and by finding/looting weapons and items the players increase their chances of survival. The game boasts one of the best character customisation systems seen in any game (AAA or indie) and incorporates survival elements like hunger and thirst, which gradually grow over time. Supplies such as food and water can be found to battle the hunger and thirst. If the player fails to properly quench their hunger and thirst, the player''s character will eventually die thus, continuing the cycle of life and death in the game. Unlike other similar projects there is no plan to add player vs player (PvP) combat.' FROM games WHERE igdb_id = 24943 ON CONFLICT (game_id, language_code) DO NOTHING;
